interface Element { accept(op: Operation): void }
class ElementA implements Element { accept(op: Operation) { op.applyToA(this) } }
class ElementB implements Element { accept(op: Operation) { op.applyToB(this) } }
interface Operation { applyToA(a: ElementA): void; applyToB(b: ElementB): void }
class PrintOperation implements Operation { applyToA(a: ElementA) { console.log('A') } applyToB(b: ElementB) { console.log('B') } }

